"use client";
import { businessOverview } from "@/lib/vendor-demo/operations";
import { dateKey, dateLabel, type HubState, type VendorEvent } from "@/lib/vendor-demo/model";
import { useVendorInquiries } from "./useVendorInquiries";
import { Panel, buttonClass, secondaryClass } from "./HubForms";
export function Overview({state,openEvent,navigate,addEvent}:{state:HubState;openEvent:(event:VendorEvent)=>void;navigate:(section:"Calendar"|"Inquiries"|"Marketplace Listing"|"Availability")=>void;addEvent:()=>void}) {
  const now=new Date();
  const info=businessOverview(state,dateKey(now),`${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`);
  const inquiries=useVendorInquiries();
  const needsReply=inquiries.filter(({item})=>!item.response);
  const quoted=inquiries.filter(({item})=>item.response?.status === "quoted");
  const row=(e:VendorEvent)=><button key={e.id} onClick={()=>openEvent(e)} className="operation-event"><span><strong>{e.name}</strong><span>{dateLabel(e.date)} · {e.start}–{e.end}</span><span>{e.client} · {e.source === "ARIVVIO" ? "ARIVVIO demo" : "External"}</span></span><span className={`event-${e.status.toLowerCase()} rounded-md px-2 py-1 text-xs`}>{e.status}</span></button>;
  return <div className="operations-home"><div className="space-y-6"><Panel title="Today’s schedule"><p className="mb-4 text-sm ui-muted">{dateLabel(dateKey(now))} · {info.today.label}</p>{info.today.events.length?info.today.events.map(row):<p className="py-4 ui-muted">No events scheduled today.</p>}<button className={`${secondaryClass} mt-4`} onClick={()=>navigate("Calendar")}>Open calendar</button></Panel><Panel title="Next on your calendar">{info.next ? row(info.next) : <p className="ui-muted">Your next event will appear here.</p>}<button className={`${buttonClass} mt-4`} onClick={addEvent}>Add external booking</button></Panel><Panel title="Coming up">{info.upcoming.filter(e=>e.id!==info.next?.id).slice(0,4).map(row)}{info.upcoming.length<2&&<p className="ui-muted text-sm">No other upcoming events.</p>}</Panel></div><div className="space-y-6"><Panel title="Needs your attention"><button className="operation-event" onClick={()=>navigate("Inquiries")}><span><strong>{needsReply.length} inquiries need a reply</strong><span>{quoted.length} demo quotes recorded · Customer decisions remain in the request</span></span><span>↗</span></button>{info.attention.slice(0,3).map(({event,warnings})=><button className="mt-4 block w-full rounded-lg bg-amber-50 p-3 text-left text-sm text-amber-900" key={event.id} onClick={()=>openEvent(event)}><strong>{event.name}</strong><span className="mt-1 block">{warnings.join(" ")}</span></button>)}{!info.attention.length&&<p className="mt-4 text-sm ui-muted">No scheduling warnings on upcoming events.</p>}</Panel><Panel title="Your business at a glance"><p className="text-sm">Today: {info.today.hours.enabled?`${info.today.hours.start}–${info.today.hours.end}`:"Outside working hours"}{info.today.blocked?" · Date blocked":""}</p><button className="mt-3 text-sm underline" onClick={()=>navigate("Availability")}>Manage availability</button><div className="mt-5 border-t ui-border pt-5"><p className="font-semibold">Marketplace listing</p><p className="mt-2 text-sm ui-muted">{info.checks.filter(c=>c.done).length} of {info.checks.length} essentials complete. Local demo preview only.</p>{info.checks.filter(c=>!c.done).map(c=><p key={c.label} className="mt-2 text-xs ui-muted">Add {c.label.toLowerCase()}</p>)}<button className={`${secondaryClass} mt-4`} onClick={()=>navigate("Marketplace Listing")}>Edit listing and preview</button></div></Panel><Panel title="Recent activity">{(state.notices??[]).slice(0,3).map(n=><p key={n.id} className="border-b ui-border py-3 text-sm">{n.title}<span className="mt-1 block text-xs ui-muted">{n.body}</span></p>)}</Panel></div></div>;
}
